CREATE SCHEMA IF NOT EXISTS private;
REVOKE ALL ON SCHEMA private FROM PUBLIC, anon, authenticated;
GRANT USAGE ON SCHEMA private TO authenticated, service_role;
ALTER FUNCTION public.has_role(uuid,public.app_role) SET SCHEMA private;
ALTER FUNCTION public.my_advertiser_id() SET SCHEMA private;
ALTER FUNCTION public.create_my_advertiser(text) SET SCHEMA private;
ALTER FUNCTION public.ingest_click(text,text,text,timestamptz,text,text,text) SET SCHEMA private;
REVOKE ALL ON FUNCTION private.has_role(uuid,public.app_role) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION private.my_advertiser_id() FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION private.create_my_advertiser(text) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION private.ingest_click(text,text,text,timestamptz,text,text,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION private.has_role(uuid,public.app_role), private.my_advertiser_id() TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION private.create_my_advertiser(text), private.ingest_click(text,text,text,timestamptz,text,text,text) TO service_role;
CREATE OR REPLACE FUNCTION private.create_my_advertiser(_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Use the authorized account setup service'; END $$;
CREATE OR REPLACE FUNCTION private.ingest_click(_event_id text,_ad_id text,_viewer_id text,_event_time timestamptz,_country text,_device text,_ip_hash text DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _ad public.ads%ROWTYPE; _window timestamptz; _inserted int; _repeat int; _ip_count int; BEGIN IF current_user <> 'service_role' THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF length(_event_id)<8 OR length(_event_id)>120 OR length(_viewer_id)<1 OR length(_viewer_id)>120 OR _country !~ '^[A-Z]{2}$' OR _device NOT IN ('mobile','desktop','tablet','other') OR _event_time < now()-interval '24 hours' OR _event_time > now()+interval '5 minutes' THEN RAISE EXCEPTION 'Invalid click'; END IF; SELECT * INTO _ad FROM public.ads WHERE id=_ad_id; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown ad'; END IF; _window:=date_trunc('minute',_event_time); INSERT INTO public.click_events(event_id,ad_id,campaign_id,advertiser_id,viewer_id,event_time,ip_hash,country,device) VALUES(_event_id,_ad_id,_ad.campaign_id,_ad.advertiser_id,_viewer_id,_event_time,_ip_hash,_country,_device) ON CONFLICT DO NOTHING; GET DIAGNOSTICS _inserted=ROW_COUNT; IF _inserted=0 THEN RETURN false; END IF; INSERT INTO public.aggregated_clicks(window_start,advertiser_id,campaign_id,ad_id,country,device,click_count,unique_viewers) VALUES(_window,_ad.advertiser_id,_ad.campaign_id,_ad_id,_country,_device,1,CASE WHEN EXISTS(SELECT 1 FROM public.click_events e WHERE e.ad_id=_ad_id AND e.viewer_id=_viewer_id AND date_trunc('minute',e.event_time)=_window AND e.event_id<>_event_id) THEN 0 ELSE 1 END) ON CONFLICT(window_start,ad_id,country,device) DO UPDATE SET click_count=public.aggregated_clicks.click_count+1,unique_viewers=public.aggregated_clicks.unique_viewers+EXCLUDED.unique_viewers; SELECT count(*) INTO _repeat FROM public.click_events WHERE viewer_id=_viewer_id AND ad_id=_ad_id AND event_time>=_window AND event_time<_window+interval '1 minute'; IF _repeat>=50 THEN INSERT INTO public.suspicious_clicks(advertiser_id,campaign_id,ad_id,rule,subject,click_count,window_start) VALUES(_ad.advertiser_id,_ad.campaign_id,_ad_id,'viewer_repeat',_viewer_id,_repeat,_window) ON CONFLICT(rule,subject,ad_id,window_start) DO UPDATE SET click_count=EXCLUDED.click_count; END IF; IF _ip_hash IS NOT NULL THEN SELECT count(*) INTO _ip_count FROM public.click_events WHERE ip_hash=_ip_hash AND event_time>=date_trunc('minute',_event_time)+floor(extract(second from _event_time)/10)*interval '10 seconds' AND event_time<date_trunc('minute',_event_time)+(floor(extract(second from _event_time)/10)+1)*interval '10 seconds'; IF _ip_count>=100 THEN INSERT INTO public.suspicious_clicks(advertiser_id,campaign_id,ad_id,rule,subject,click_count,window_start) VALUES(_ad.advertiser_id,_ad.campaign_id,_ad_id,'ip_burst',_ip_hash,_ip_count,date_trunc('minute',_event_time)+floor(extract(second from _event_time)/10)*interval '10 seconds') ON CONFLICT(rule,subject,ad_id,window_start) DO UPDATE SET click_count=EXCLUDED.click_count; END IF; END IF; RETURN true; END $$;